  add('solid','advanced','立方体の展開図を切り開いたとき、組み立てるとふちの辺どうしが何組合わさりますか。',7,[5,6,12],['展開図のまわりの辺（外側の辺）の数を考えます。','正方形６まいの辺は全部で24本、つながっている辺が５か所あります。'],'正方形６まいの辺は24本。つながっている５か所は、２本ずつ合わせて10本なので、外側の辺は24－10＝14本です。２本が組になって合わさるので、14 ÷ 2＝７組です。',{"kind":"boxNet","dimensions":[1,1,1],"showLengths":false,"caption":"立方体を開いた図。外側の辺どうしを考えよう"});
  add('solid','advanced','立方体のほね組みを作ったら、ひごを全部で60cm使いました。この立方体の１辺は何cmですか。',5,[6,10,15],['立方体には辺が12本あります。','全部の長さを辺の数でわります。'],'60 ÷ 12＝５。１辺は５cmです。',null);
  add('solid','advanced','直方体のほね組みを作ったら、ひごを全部で52cm使いました。たてが５cm、横が４cmのとき、高さは何cmですか。',4,[3,5,13],['辺はたて・横・高さが４本ずつです。','52を４でわって、たて＋横＋高さを求めます。'],'52 ÷ 4＝13。13－5－4＝４。高さは４cmです。',null);
  add('solid','advanced','１辺が２cmの立方体の積み木を横に３つならべて、直方体を作りました。この直方体の辺の長さは、全部で何cmですか。',40,[36,32,24],['直方体のたて・横・高さを先に求めます。','横は２cm × ３です。'],'横は６cm、たては２cm、高さも２cmです。4 ×（6＋2＋2）＝40cmです。',null);
  add('solid','advanced','たて４cm、横３cm、高さ２cmの直方体の、６つの面の面積を全部合わせると、何cm²ですか。',52,[24,26,48],['向かい合う面は同じ面積です。','たて×横たて×高さ、横×高さの３種類を考えます。'],'4 × 3＝12、4 × 2＝８、3 × 2＝６。それぞれ２まいずつなので、（12＋8＋6）× 2＝52cm²です。',null);
  add('solid','advanced','立方体の頂点Ａから、辺にそって進んで、いちばん遠い頂点Ｇまで行きます。辺を何本通れば最短ですか。',3,[2,4,6],['Ａから見てたて・横・高さ、それぞれ１回ずつ進みます。','ななめには進めません。'],'いちばん遠い頂点へは、横・たて・高さの順に１本ずつ、全部で３本通れば行けます。',{"kind":"solid3d","shape":"cube","vertices":[{"vertex":"A","label":"Ａ"},{"vertex":"G","label":"Ｇ"}],"caption":"ＡからＧへ辺にそって進む。道すじは自分で考えよう"});
  add('solid','advanced','たて６cm、横４cm、高さ４cmの箱に、１辺２cmの立方体の積み木をすきまなくつめます。積み木は何こ入りますか。',12,[24,48,96],['たて・横・高さにそれぞれ何こならぶか考えます。','６ ÷ ２、４ ÷ ２、４ ÷ ２です。'],'たてに３こ横に２こ、高さに２だんなので、3 × 2 × 2＝12こです。',{"kind":"solid3d","shape":"box","vertices":[],"caption":"箱と積み木１こ。すきまなく入れるときのならび方を考えよう","dimensions":[4,6,4],"showLengths":true,"unit":"cm","block":2});
  add('solid','advanced','雪原基地の倉庫に木箱をたてに３こ、横に４こならべ、それを２だんに積みます。木箱は全部で何こですか。',24,[12,14,18],['１だんに何こならぶか先に求めます。','それにだんの数をかけます。'],'１だんは 3 × 4＝12こ。２だんなので、12 × 2＝24こです。',null);
  add('solid','advanced','直方体の頂点Ａを（０、０、０）として、右へ３、奥へ２、高さ４の頂点を（３、２、４）と表します。この頂点と同じ高さにある頂点は、全部で何こですか。（その頂点も数えます）',4,[1,2,8],['高さが同じ頂点は、同じ面の上にあります。','上の面（高さ４）の頂点を数えます。'],'高さ４の面（上の面）には頂点が４つあります。その頂点と同じ高さの頂点は、４こです。',null);
  add('solid','advanced','たて５cm、横３cm、高さ２cmの直方体で、いちばん面積が大きい面の面積は何cm²ですか。',15,[6,10,30],['面の種類は３つあります。','いちばん長い辺どうしの面を選びましょう。'],'面積は5 × 3＝15、5 × 2＝10、3 × 2＝６。いちばん大きいのは15cm²です。',null);
  // 垂直・平行と四角形（30問）
  add('quad','basic','平行四辺形で、向かい合う辺が平行になっている組は、何組ありますか。',2,[1,3,4],['向かい合う辺は、上と下、左と右の組があります。','どちらの組も平行です。'],'平行四辺形は向かい合う２組の辺がどちらも平行です。',null);
  add('quad','basic','長方形の４つの角は、それぞれ何度ですか。',90,[60,180,360],['長方形の角はすべて同じ大きさです。','直角は何度でしょう。'],'長方形の角は４つとも直角で90度です。',null);
  add('quad','basic','正方形の特ちょうとして、正しいものはどれですか。','４つの角が直角で４つの辺の長さが等しい',['４つの角が直角だが辺の長さはちがうこともある','辺の長さは等しいが角は直角でないこともある','向かい合う辺が平行ではない'],['正方形は長方形でもあり、ひし形でもあります。','角と辺の両方を考えましょう。'],'正方形は、４つの角が直角（長方形の特ちょう）で、４つの辺の長さが等しい（ひし形の特ちょう）四角形です。',null);
  add('quad','basic','平行四辺形ＡＢＣＤで角Ａが70度のとき、向かい合う角Ｃは何度ですか。',70,[110,20,290],['平行四辺形の向かい合う角は、大きさが等しくなります。','角Ａの向かい側の角を考えます。'],'平行四辺形の向かい合う角は等しいので、角Ｃも70度です。',{"kind":"quadFigure","shape":"parallelogram","angle":70,"caption":"平行四辺形の向かい合う角を考えよう"});
  add('quad','basic','台形で向かい合う辺が平行になっている組は、何組ですか。',1,[0,2,4],['台形は向かい合う１組の辺だけが平行な四角形です。','平行四辺形とのちがいを考えましょう。'],'台形は向かい合う１組の辺だけが平行です。',null);
  add('quad','basic','四角形の対角線は、何本引けますか。',2,[1,3,4],['向かい合う頂点を結ぶ線が対角線です。','頂点が４つあるので、向かい合う組を数えます。'],'向かい合う頂点の組が２組あるので、対角線は２本です。',null);
  add('quad','basic','１辺が５cmのひし形があります。まわりの長さは何cmですか。',20,[10,15,25],['ひし形は４つの辺の長さがすべて等しい四角形です。','１辺の長さに辺の数をかけます。'],'5 × 4＝20。まわりの長さは20cmです。',null);

  add('quad','standard','平行四辺形ＡＢＣＤで角Ａが70度のとき、となり合う角Ｂは何度ですか。',110,[70,20,290],['平行四辺形のとなり合う角を足すと180度になります。','180度から70度を引きます。'],'180－70＝110。角Ｂは110度です。',null);
  add('quad','standard','平行四辺形ＡＢＣＤで辺ＡＢが８cm、辺ＢＣが５cmです。まわりの長さは何cmですか。',26,[13,40,21],['向かい合う辺の長さは等しいです。','８cmの辺と５cmの辺がそれぞれ２本ずつあります。'],'（8＋5）× 2＝26。まわりの長さは26cmです。',null);
  add('quad','standard','ひし形の２本の対角線は、どのように交わりますか。','垂直に交わる',['平行になる','交わらない','長さが必ず等しくなる'],['ひし形の対角線を引いた図を思いうかべましょう。','交わってできる角は直角です。'],'ひし形の２本の対角線は、おたがいの真ん中で垂直に交わります。',null);
  add('quad','standard','平行四辺形ＡＢＣＤの対角線ＡＣとＢＤが点Ｏで交わっています。ＡＣが10cmのとき、ＡＯは何cmですか。',5,[10,20,2],['平行四辺形の対角線は、おたがいの真ん中で交わります。','ＡＣを２等分した長さがＡＯです。'],'点Ｏは対角線の真ん中なので、ＡＯ＝10 ÷ 2＝５cmです。',{"kind":"quadFigure","shape":"parallelogram","diagonal":10,"unknown":"ＡＯ","unit":"cm","caption":"２本の対角線の交点がＯ。長さのきまりを考えよう"});
  add('quad','standard','四角形の４つの角の大きさを合わせると何度になりますか。',360,[180,270,720],['四角形は対角線で２つの三角形に分けられます。','三角形の角の和は180度です。'],'三角形２つ分なので、180 × 2＝360。４つの角の和は360度です。',null);
  add('quad','standard','四角形の３つの角が90度、80度、100度です。残りの角は何度ですか。',90,[80,100,270],['四角形の角の和は360度です。','わかっている３つの角を足して、360度から引きます。'],'90＋80＋100＝270。360－270＝90。残りの角は90度です。',null);
  add('quad','standard','台形で、平行になっている２つの辺をそれぞれ何といいますか。','上底と下底',['高さと底辺','対角線と対辺','直線と曲線'],['平行な辺の上の方と下の方に名前があります。','「底」という字のつく名前です。'],'台形の平行な２つの辺は、上の辺を上底、下の辺を下底といいます。',null);
  add('quad','standard','直線ａと直線ｂが垂直で直線ｃも直線ｂに垂直です。直線ａと直線ｃは、どんな関係ですか。','平行',['垂直','交わって、直角にならない','同じ直線になる'],['直線ｂに垂直な直線は、すべて同じ向きになります。','同じ直線に垂直な２本の直線は、どこまでも交わりません。'],'同じ直線に垂直な２本の直線は、平行になります。',null);
  add('quad','standard','直線ａと直線ｂは平行で直線ｃが直線ａに垂直です。直線ｃと直線ｂは、どんな関係ですか。','垂直',['平行','ななめに交わる','関係はない'],['平行な直線は同じ向きにのびています。','直線ａと同じ角度で直線ｃに交わります。'],'平行な直線の一方に垂直な直線は、もう一方にも垂直です。',null);
  add('quad','standard','まわりの長さが36cmのひし形があります。１辺は何cmですか。',9,[6,12,18],['ひし形は４つの辺の長さがすべて等しいです。','まわりの長さを辺の数でわります。'],'36 ÷ 4＝９。１辺は９cmです。',null);
  add('quad','standard','平行な２本の直線の間のはばはどこではかっても、どうなりますか。','いつも同じ',['右に行くほど広くなる','右に行くほどせまくなる','はかる場所によって変わる'],['平行な直線は交わらず、はなれ方も変わりません。','直線に垂直にはかります。'],'平行な直線はどこではかっても、間のはばがいつも同じです。',null);
  add('quad','standard','正方形の２本の対角線には、どんな特ちょうがありますか。','長さが等しく垂直に交わる',['長さが等しいが垂直には交わらない','垂直に交わるが長さは等しくない','長さも等しくなく垂直にも交わらない'],['正方形は長方形でもあり、ひし形でもあります。','長方形の対角線とひし形の対角線の特ちょうを合わせます。'],'正方形の対角線は、長方形のように長さが等しくひし形のように垂直に交わります。',null);

  add('quad','advanced','平行四辺形ＡＢＣＤで角Ａが角Ｂの２倍の大きさです。角Ａは何度ですか。',120,[60,90,100],['角Ａと角Ｂはとなり合う角です。足すと180度になります。','角Ｂを□度として、角Ａ＝□×２で考えます。'],'角Ａ＋角Ｂ＝180度で角Ａは角Ｂの２倍です。角Ｂ＝180 ÷ 3＝60度、角Ａ＝60 × 2＝120度です。',null);
  add('quad','advanced','四角形の４つの角のうち、２つが85度と95度で残りの２つの角は同じ大きさです。残りの角はそれぞれ何度ですか。',90,[85,95,180],['四角形の角の和は360度です。','85＋95を先に計算し、残りを２でわります。'],'85＋95＝180。360－180＝180。２つの角が同じなので、180 ÷ 2＝90。それぞれ90度です。',null);
  add('quad','advanced','まわりの長さが36cmの平行四辺形があります。辺ＡＢが７cmのとき、辺ＢＣは何cmですか。',11,[18,22,29],['向かい合う辺の長さは等しいです。','まわりの長さの半分がＡＢ＋ＢＣです。'],'36 ÷ 2＝18。18－7＝11。辺ＢＣは11cmです。',null);
  add('quad','advanced','長方形ＡＢＣＤの対角線ＡＣとＢＤが点Ｏで交わります。ＡＣが14cmのとき、ＯＢは何cmですか。',7,[14,28,10],['長方形の２本の対角線は、長さが等しくおたがいの真ん中で交わります。','ＢＤの長さをまず考えましょう。'],'ＢＤ＝ＡＣ＝14cmで点ＯはＢＤの真ん中なので、ＯＢ＝14 ÷ 2＝７cmです。',{"kind":"quadFigure","shape":"rectangle","diagonal":14,"unknown":"ＯＢ","unit":"cm","caption":"長方形の対角線と交点Ｏ。長さのきまりを考えよう"});
  add('quad','advanced','２本の対角線が長さが等しく垂直に交わり、おたがいの真ん中で交わる四角形は、どれですか。','正方形',['長方形','ひし形','平行四辺形'],['長さが等しい対角線をもつのは、どの四角形でしょう。','垂直に交わる対角線をもつのは、どの四角形でしょう。'],'対角線の長さが等しいのは長方形、垂直に交わるのはひし形です。その両方をもつのは正方形です。',null);
  add('quad','advanced','次の四角形のうち、２本の対角線がいつも垂直に交わるものは、どれですか。','ひし形',['長方形','平行四辺形','台形'],['対角線を引いた図をそれぞれ思いうかべます。','４つの辺の長さが等しい四角形です。'],'ひし形の対角線は、いつも垂直に交わります。長方形や平行四辺形は、垂直に交わらないこともあります。',null);
  add('quad','advanced','向かい合う辺が２組とも平行で４つの角がすべて等しい四角形は、どれですか。','長方形',['ひし形','台形','平行四辺形'],['４つの角がすべて等しいとそれぞれ何度でしょう。','角が全部直角で、向かい合う辺が平行な四角形です。'],'４つの角の和は360度なので、すべて等しければ90度ずつです。向かい合う辺が平行で４つの角が直角なのは、長方形です。',null);
  add('quad','advanced','４つの角がすべて直角である四角形を、すべて選んだものはどれですか。','正方形と長方形',['正方形とひし形','ひし形と平行四辺形','長方形とひし形'],['ひし形は角が直角でないこともあります。','平行四辺形も角が直角でないこともあります。'],'正方形と長方形は、４つの角がすべて直角です。ひし形や平行四辺形は、直角にならないこともあります。',null);
  add('quad','advanced','雪原基地の看板は、辺ＡＢが９cm、辺ＢＣが６cmの平行四辺形です。ふちに紙テープを２周まくとテープは何cm必要ですか。（つなぎ目は考えません）',60,[30,15,54],['１周分のまわりの長さを先に求めます。','それを２倍します。'],'１周は（9＋6）× 2＝30cm。２周分は 30 × 2＝60cmです。',{"kind":"quadFigure","shape":"parallelogram","sides":[9,6],"unit":"cm","caption":"看板の２つの辺の長さ。テープの長さは自分で考えよう"});
  add('quad','advanced','ひし形ＡＢＣＤで角Ａが50度のとき、となり合う角Ｂは何度ですか。',130,[50,40,310],['ひし形は平行四辺形の仲間です。','となり合う角を足すと180度になります。'],'180－50＝130。角Ｂは130度です。',null);
  add('quad','advanced','正方形ＡＢＣＤで辺ＡＢに平行な辺は何本、垂直な辺は何本ありますか。','平行１本、垂直２本',['平行２本、垂直１本','平行１本、垂直１本','平行２本、垂直２本'],['正方形の辺を１つずつ、辺ＡＢと比べましょう。','向かい合う辺は平行、となり合う辺は垂直です。'],'辺ＡＢに平行なのは向かい合う辺ＤＣの１本、垂直なのはとなり合う辺ＡＤとＢＣの２本です。',null);
  // 折れ線グラフ（30問）
  add('graph','basic','図は雪原基地の積雪の深さです。２月の積雪は何cmですか。',55,[40,35,12],['２月の点を探します。','その点の高さを左の目もりで読みます。'],'２月の点は55の高さにあるので、55cmです。',SNOW);
  add('graph','basic','図の積雪の深さがいちばん深いのは何月ですか。','２月',['１月','３月','４月'],['グラフのいちばん高い点を探します。','その下の月を読みます。'],'いちばん高い点は55cmの２月です。',SNOW);
  add('graph','basic','折れ線グラフは、どんなことを表すのにむいていますか。','時間とともに変わっていくようす',['ものの数の多さをくらべること','全体のうちわけを見ること','ものの形を調べること'],['気温や水の量などを時間を追って表したグラフです。','線のかたむきで、変わり方がわかります。'],'折れ線グラフは、時間とともに量が変わっていくようすを表すのにむいています。',null);
  add('graph','basic','折れ線グラフで、線が右上がりになっているところは、どんなようすですか。','だんだん増えている',['だんだんへっている','変わっていない','最初の量と同じ'],['右にいくほど、点が高くなっています。','点が高いほど、量は大きいです。'],'右上がりの線は、量が増えていることを表します。',null);
  add('graph','basic','図は１週間に使ったまきの数です。火曜日は何本ですか。',26,[20,24,18],['火曜日の点を探します。','左の目もりで高さを読みます。'],'火曜日の点は26の高さなので、26本です。',{"kind":"graph","values":[20,26,24,18,18,30],"labels":["月","火","水","木","金","土"],"caption":"まきの数（本）","minorStep":1});
  add('graph','basic','折れ線グラフで、線が横にまっすぐになっているところは、どんなようすですか。','変わっていない',['増えている','へっている','わからない'],['左と右で、点の高さを比べます。','高さが同じなら、量は同じです。'],'横にまっすぐな線は、量が変わっていないことを表します。',null);
  add('graph','basic','図は水そうに入っている水の量です。10分のとき、水は何Lですか。',50,[30,70,10],['10分の点を探します。','その点の高さを読みます。'],'10分の点は50の高さなので、50Lです。',WATER);

  add('graph','standard','図の積雪の深さは、３月から４月までに何cmへりましたか。',23,[12,35,47],['３月と４月の深さを読みます。','前の月からあとの月を引きます。'],'３月は35cm、４月は12cmです。35－12＝23。23cmへりました。',SNOW);
