  add('abacus','basic','そろばんの上の玉１つはいくつを表しますか。',5,[1,10,50],['上の玉と下の玉では、表す大きさがちがいます。','下の玉は１つで１を表します。'],'上の玉は１つで５、下の玉は１つで１を表します。',null);
  add('abacus','basic','図のそろばんが表している数はいくつですか。',35,[53,38,305],['はりに近づけた玉を数えます。','左のけたが十の位です。'],'十の位が３、一の位が５なので35です。',abacus([3,5],['十','一']));
