  add('abacus','standard','そろばんの１つのけたで表せる数は、０からいくつまでですか。',9,[5,10,4],['上の玉は５、下の玉は４つで４までです。','上の玉と下の玉をぜんぶ使うと最大になります。'],'上の玉１つ（５）と下の玉４つ（４）を合わせると９です。10になると左のけたにくり上がります。',null);
  add('abacus','standard','図のそろばんの小数に0.5を足します。答えはいくつですか。',2.3,[1.3,2.8,2.5],['図は1.8を表しています。','十分の一の位で８＋５を計算します。'],'1.8＋0.5＝2.3です。十分の一の位が13になるので、一の位にくり上がります。',abacus([1,8],['一','十分の一']));
  add('abacus','standard','図のそろばんの数を10倍すると、いくつになりますか。',320,[32,3200,302],['図は32を表しています。','10倍すると、すべてのけたが１つ左にずれます。'],'32の10倍は320です。',abacus([3,2],['十','一']));

