  add('large','standard','０から９までの数字のカードを１まいずつ使って、10けたの数を作ります。いちばん大きい数はいくつですか。',9876543210,[9876543201,1023456789,9999999999],['大きい位から大きい数字をならべます。','９、８、７…の順にならべます。'],'大きい数字から順にならべると9876543210です。',null);
  add('large','standard','53000万は、何億何千万ですか。','5億3000万',['53億','5億300万','530億'],['10000万が１億です。','53000万＝50000万＋3000万です。'],'50000万＝５億あと3000万なので、5億3000万です。',null);

  add('large','advanced','１兆と2300億を合わせた数を数字で書きましょう。',1230000000000,[1023000000000,123000000000,12300000000000],['１兆は１のあとに０が12こ付く数です。','2300億は2300のあとに０が８こ付く数です。'],'１兆＝1000000000000、2300億＝230000000000。合わせて1230000000000です。',null);
  add('large','advanced','人口が１億2500万人の国の、10分の１の人口は何人ですか。',12500000,[1250000,125000000,1250000000],['10でわると位が１つ下がります。','１億2500万＝125000000です。'],'125000000÷10＝12500000。1250万人です。',null);
  add('large','advanced','1000万を1000倍すると、いくつになりますか。','100億',['10億','1000億','1兆'],['1000倍すると、位が３つ上がります。','1000万×1000＝10000000000です。'],'1000万×1000＝10000000000で、100億です。',null);
  add('large','advanced','０から９までの数字のカードを１まいずつ使って、10けたの数を作ります。いちばん小さい数はいくつですか。（いちばん上の位に０は使えません）',1023456789,[123456789,1000000000,987654321],['いちばん上は０以外でいちばん小さい数です。','そのあとに０、２、３…とならべます。'],'いちばん上は１、次に０、そのあと２から９を小さい順にならべると1023456789です。',null);
  add('large','advanced','ある数を10倍すると、530億になります。ある数はいくつですか。','53億',['5300億','5億3000万','530億'],['10倍する前にもとのかずを求めるには、10でわります。','530÷10＝53です。'],'530億÷10＝53億です。',null);
  add('large','advanced','ある数を100倍すると、７兆になります。ある数はいくつですか。',70000000000,[7000000000,700000000000,7000000000000],['100倍する前にもとのかずを求めるには、100でわります。','７兆は7000億です。'],'７兆÷100＝700億＝70000000000です。',null);
  add('large','advanced','１万を１万倍すると、いくつになりますか。','1億',['10億','1000万','1兆'],['10000×10000を考えます。','１のあとに０が何こ付きますか。'],'10000×10000＝100000000で１億です。',null);
  add('large','advanced','３億と２億5000万の差は、いくつですか。',50000000,[500000000,5000000,5000000000],['３億は３億0000万と書けます。','３億から２億5000万を引きます。'],'３億－２億5000万＝5000万。数字で書くと50000000です。',null);
  add('large','advanced','１兆は1000億の何倍ですか。',10,[100,1000,1],['１兆は10000億です。','1000億が何こ集まった数か考えます。'],'１兆＝10000億なので、1000億の10倍です。',null);
  add('large','advanced','十億の位が７、千万の位が４で、ほかの位がすべて０の数を、数字で書きましょう。',7040000000,[704000000,7400000000,70400000000],['十億の位は右から10番目の位です。','千万の位は右から８番目の位です。'],'十億の位が７、千万の位が４なので、7040000000です。',null);
  add('large','advanced','Ａは３億2000万、Ｂは３億200万です。どちらがいくつ大きいですか。','Ａが1800万大きい',['Ｂが1800万大きい','Ａが1億8000万大きい','Ａが180万大きい'],['３億は同じです。','2000万と200万の差を考えます。'],'３億は同じなので、2000万－200万＝1800万。Ａが1800万大きいです。',null);

  // がい数（29問）
  add('round','basic','3452を四捨五入して百の位までのがい数にしましょう。',3500,[3400,3000,3450],['百の位の１つ下の十の位を見ます。','十の位は５なので、切り上げます。'],'十の位の５を四捨五入して、3500です。',null);
  add('round','basic','四捨五入で、切り上げるのは、そのすぐ下の位の数が何以上のときですか。','５以上',['４以上','６以上','０以上'],['四捨五入の「五入」にあたる場合です。','５、６、７、８、９のときです。'],'すぐ下の位の数が５以上のときは切り上げ、４以下のときは切り捨てます。',null);
  add('round','basic','78を四捨五入して十の位までのがい数にしましょう。',80,[70,78,100],['十の位の１つ下の一の位を見ます。','一の位は８なので、切り上げます。'],'一の位の８を四捨五入して、80です。',null);
  add('round','basic','6240を四捨五入して千の位までのがい数にしましょう。',6000,[7000,6200,6300],['千の位の１つ下の百の位を見ます。','百の位は２なので、切り捨てます。'],'百の位の２を四捨五入して、6000です。',null);
  add('round','basic','「がい数」とは、どんな数ですか。','およその数',['正しい数','いちばん大きい数','整数でない数'],['「がい」は「おおよそ」という意味です。','四捨五入などで、切りのよい数にします。'],'がい数とは、おおよその数のことです。',null);
  add('round','basic','4500を四捨五入して千の位までのがい数にしましょう。',5000,[4000,4500,6000],['千の位の１つ下の百の位を見ます。','百の位はちょうど５です。５は切り上げます。'],'百の位の５は切り上げるので、5000です。',null);
  add('round','basic','49を四捨五入して十の位までのがい数にしましょう。',50,[40,49,60],['一の位を見ます。','一の位は９なので、切り上げます。'],'一の位の９を四捨五入して、50です。',null);

  add('round','standard','27648を、四捨五入して上から１けたのがい数にしましょう。',30000,[20000,28000,27000],['上から１けた目のすぐ下の位を見ます。','万の位が２、その下の千の位が７です。'],'千の位の７を四捨五入して、30000です。',null);
  add('round','standard','4562を四捨五入して上から２けたのがい数にしましょう。',4600,[4500,4560,5000],['上から２けた目は、百の位です。','その下の十の位を見ます。'],'十の位の６を四捨五入して、4600です。',null);
  add('round','standard','雪原基地の村の人が235人、バスで出かけます。バスは１台に50人まで乗れます。何台あれば全員が乗れますか。',5,[4,6,7],['235÷50を考えます。','あまりが出たら、もう１台必要です。'],'235÷50＝４あまり35。あまった35人も乗るので、５台必要です（切り上げ）。',null);
  add('round','standard','1000円で、１こ120円のおにぎりをできるだけ多く買います。何こ買えますか。',8,[9,10,7],['1000÷120を考えます。','買えるのは代金が1000円をこえない数までです。'],'1000÷120＝８あまり40。９こ買うと1080円で足りないので、８こ買えます（切り捨て）。',null);
  add('round','standard','3980円と5120円を千の位までのがい数にして足し、およその合計を求めましょう。',9000,[8000,10000,9100],['それぞれを千の位までのがい数にします。','4000と5000を足します。'],'3980→4000、5120→5000。4000＋5000＝9000円です。',null);
  add('round','standard','598×６を598を600と見て、見積もりましょう。およそいくつですか。',3600,[3000,3588,3500],['598は600に近い数です。','600×６を計算します。'],'598を600とすると、600×6＝3600。およそ3600です。',null);
  add('round','standard','四捨五入して百の位までのがい数にしたとき、5000になる整数のうち、いちばん大きい数はいくつですか。',5049,[5000,5050,4999],['５０００になるはんいは、4950から5049までです。','5050は切り上げて5100になります。'],'十の位が４までなら切り捨てて5000です。いちばん大きいのは5049です。',null);
  add('round','standard','100以上200未満の整数のうち、いちばん小さい数はいくつですか。',100,[99,101,200],['以上はその数をふくみます。','100以上なので、100も入ります。'],'100以上は100をふくむので、いちばん小さい数は100です。',null);
  add('round','standard','次の数のうち、四捨五入して千の位までのがい数にすると4000になる数を選びましょう。','3600',['3400','4600','4500'],['千の位まで四捨五入するので、百の位を見ます。','3500以上4499以下の数が4000になります。'],'3600は百の位の６を切り上げて4000になります。3400は3000、4500は5000です。',null);
  add('round','standard','村の人口は23547人です。四捨五入して万の位までのがい数にすると、約何人ですか。',20000,[24000,23000,30000],['万の位の１つ下の千の位を見ます。','千の位は３なので、切り捨てます。'],'千の位の３を四捨五入して、20000人です。',null);
  add('round','standard','3470を四捨五入して上から１けたのがい数にしましょう。',3000,[3500,3400,4000],['上から１けた目は千の位です。','その下の百の位を見ます。'],'百の位の４を四捨五入して、3000です。',null);

  add('round','advanced','四捨五入して百の位までのがい数にすると3500になる整数のはんいは、どれですか。','3450以上3549以下',['3500以上3599以下','3400以上3499以下','3450以上3550以下'],['百の位までなので、十の位を見ます。','切り上げて3500になるのは3450から、切り捨てて3500になるのは3549までです。'],'3450から3549までの整数が、百の位までのがい数にすると3500になります。',null);
  add('round','advanced','四捨五入して十の位までのがい数にすると60になる整数は、全部で何こありますか。',10,[9,11,5],['55から64までを数えます。','55、56、…、64です。'],'55以上64以下の整数なので、64－55＋1＝10こです。',null);
  add('round','advanced','498円、302円、1198円の品物を買います。それぞれ百の位までのがい数にして、およその代金を求めましょう。',2000,[1900,2100,1998],['それぞれ500円、300円、1200円になります。','それらを足します。'],'500＋300＋1200＝2000。およそ2000円です。',null);
  add('round','advanced','全員で183人います。１台に40人まで乗れるバスで出かけるとき、バスは何台必要ですか。',5,[4,6,3],['183÷40を計算します。','あまりの人も乗るので、もう１台必要です。'],'183÷40＝４あまり23。あまった23人も乗るので、５台必要です。',null);
  add('round','advanced','１つのテントに５人まで入れます。47人がテントに入るには、テントは何はり必要ですか。',10,[9,11,8],['47÷5を計算します。','あまりの２人のために、もう１はり必要です。'],'47÷5＝９あまり２。あまりの２人のためにもう１はり必要で10はりです。',null);
  add('round','advanced','1000円を持っています。298円、385円、217円の品物を買います。それぞれ百の位までのがい数にして見積もると、代金が1000円で足りるかどうか、次のうちどれですか。','足りる',['足りない','ちょうどになる','見積もれない'],['それぞれ300円、400円、200円になります。','合計を1000円と比べます。'],'300＋400＋200＝900円で、1000円より少ないので足ります（本当は900円）。',null);
  add('round','advanced','四捨五入して千の位までのがい数にすると12000になる整数のはんいは、どれですか。','11500以上12499以下',['12000以上12999以下','11000以上11999以下','11500以上12500以下'],['百の位を見て四捨五入します。','切り上げて12000になるのは11500から、切り捨てて12000になるのは12499までです。'],'11500以上12499以下の整数が、千の位までのがい数にすると12000になります。',null);
  add('round','advanced','３けたの整数で、四捨五入して百の位までのがい数にすると400になる、いちばん小さい数はいくつですか。',350,[300,349,399],['350から399までは、切り上げて400です。','349は切り捨てて300です。'],'十の位が５以上の350から切り上げて400になります。350が最小です。',null);
  add('round','advanced','四捨五入して十の位までのがい数にすると350になる整数のうち、いちばん大きい数はいくつですか。',354,[349,355,359],['一の位を見て四捨五入します。','切り捨てて350になるのは、一の位が４までです。'],'350から354までは切り捨てて350になります。355は切り上げて360です。いちばん大きいのは354です。',null);
  add('round','advanced','4180×39を、それぞれ上から１けたのがい数にして見積もりましょう。およそいくつですか。',160000,[120000,156000,200000],['4180は4000、39は40になります。','4000×40を計算します。'],'4180→4000、39→40。4000×40＝160000です。',null);
  add('round','advanced','2500mlの水を1000mlの入れ物に入れていきます。入れ物は何こ必要ですか。',3,[2,4,25],['2500÷1000を計算します。','あまった水も入れ物に入れます。'],'2500÷1000＝２あまり500。あまりの水のためにもう１こ必要で３こです。',null);
  // １けたでわるわり算（29問）
  add('divide1','basic','68÷2を計算しましょう。',34,[24,36,44],['68を60と８に分けて考えます。','60÷2と８÷2を合わせます。'],'60÷2＝30、8÷2＝4。30＋4＝34です。',null);
  add('divide1','basic','75÷5を計算しましょう。',15,[14,16,25],['75を50と25に分けて考えます。','50÷5と25÷5を合わせます。'],'50÷5＝10、25÷5＝5。10＋5＝15です。',null);
  add('divide1','basic','17÷5の商とあまりを求めましょう。','３あまり２',['２あまり３','３あまり１','４あまり２'],['５のだんの九九で17に近い数を探します。','5×3＝15、17－15を計算します。'],'5×3＝15、17－15＝2。商は３、あまりは２です。',null);
  add('divide1','basic','わり算で、あまりはわる数より大きいですか小さいですか。','小さい',['大きい','同じ','決まっていない'],['あまりがわる数より大きいともう１回われてしまいます。','わる数が５のとき、あまりは０から４までです。'],'あまりはいつもわる数より小さくなります。',null);
  add('divide1','basic','36÷4＝９を使って、360÷4を計算しましょう。',90,[9,900,40],['360は36の10倍です。','答えも10倍になります。'],'360÷4は36÷4の10倍なので、９×10＝90です。',null);
  add('divide1','basic','わり算の答えの確かめでは、「わる数×商＋あまり」を計算します。この答えは何と同じになりますか。','わられる数',['わる数','商','あまり'],['わり算の式はわられる数＝わる数×商＋あまり、と書けます。','たとえば、17÷5＝３あまり２では5×3＋2＝17です。'],'わる数×商＋あまりは、わられる数と同じになります。',null);
  add('divide1','basic','54÷6を計算しましょう。',9,[8,7,48],['６のだんの九九を使います。','6×9＝54です。'],'6×9＝54なので、54÷6＝9です。',null);

  add('divide1','standard','235÷5を計算しましょう。',47,[57,46,45],['23÷5＝４あまり３から始めます。','あまりの３と一の位の５で35÷5を計算します。'],'235÷5＝47です。5×47＝235で確かめられます。',null);
  add('divide1','standard','625÷5を計算しましょう。',125,[115,135,25],['62÷5＝12あまり２から始めます。','あまりの２と一の位の５で25÷5を計算します。'],'625÷5＝125です。',null);
  add('divide1','standard','407÷7を計算しましょう。商とあまりを求めます。','58あまり１',['58','57あまり８','508あまり１'],['40÷7＝５あまり５から始めます。','あまりの５と一の位の７で57÷7を計算します。'],'407÷7＝58あまり１です。7×58＋1＝407で確かめられます。',null);
  add('divide1','standard','雪原基地で、あめ100こを６人に同じ数ずつ分けます。１人分は何こで、何こあまりますか。','１人16こで、４こあまる',['１人17こで、２こあまる','１人16こで、６こあまる','１人15こで、10こあまる'],['100÷6を計算します。','あまりはわる数の６より小さくなります。'],'100÷6＝16あまり４。１人16こで、４こあまります。',null);
  add('divide1','standard','832÷4の商は、何けたの数ですか。','３けた',['２けた','４けた','１けた'],['８÷４の商が立つか考えます。','百の位から商が立ちます。'],'８÷４＝２で百の位から商が立つので、商は３けたです（208）。',null);
  add('divide1','standard','ある数を５でわると商が17、あまりが３になります。ある数はいくつですか。',88,[85,20,82],['わり算の答えの確かめをさかさまに使います。','わる数×商＋あまり、を計算します。'],'5×17＋3＝85＋3＝88です。',null);
  add('divide1','standard','612÷6を計算しましょう。',102,[12,112,1002],['61÷6＝10あまり１から考えます。','十の位に商が立つので、百の位は１、十の位は０です。'],'612÷6＝102です。6×102＝612で確かめられます。',null);
  add('divide1','standard','折り紙365まいを７人に同じ数ずつ分けます。１人分は何まいで何まいあまりますか。','１人52まいで、１まいあまる',['１人52まいで、７まいあまる','１人53まいで、１まいあまる','１人51まいで、８まいあまる'],['365÷7を計算します。','7×52＝364です。'],'365÷7＝52あまり１。１人52まいで、１まいあまります。',null);
  add('divide1','standard','504÷8を計算しましょう。',63,[53,64,73],['50÷8＝６あまり２から始めます。','あまりの２と一の位の４で24÷8を計算します。'],'504÷8＝63です。8×63＝504で確かめられます。',null);
  add('divide1','standard','３m60cmのリボンを４つに同じ長さで切ります。１つは何cmですか。',90,[9,80,900],['まず、360cmと考えます。','360÷4を計算します。'],'３m60cm＝360cm。360÷4＝90。１つは90cmです。',null);
  add('divide1','standard','40000÷8を計算しましょう。',5000,[500,50000,4000],['4÷8はわれないので、40÷8から考えます。','40÷8＝５を使います。'],'40÷8＝５を使って、40000÷8＝5000です。',null);

  add('divide1','advanced','ある数を７でわると商が24、あまりが５になります。ある数はいくつですか。',173,[168,29,163],['わる数×商＋あまりでもとの数が求まります。','7×24を先に計算します。'],'7×24＝168。168＋5＝173です。',null);
  add('divide1','advanced','ある数を６でわるとき、あまりとして考えられるいちばん大きい数はいくつですか。',5,[6,4,1],['あまりはわる数より小さい数です。','６でわるときのあまりは、０から何までか考えます。'],'あまりはわる数より小さいので、６でわるときは０から５までです。いちばん大きいのは５です。',null);
  add('divide1','advanced','□÷９＝12あまり□ であまりがいちばん大きいとき、わられる数はいくつですか。',116,[108,117,115],['９でわるときのあまりの最大は、８です。','９×12にあまりの８を足します。'],'９でわるときのあまりの最大は８です。9×12＋8＝108＋8＝116です。',null);
  add('divide1','advanced','365この荷物を８こ入りの箱につめます。全部の荷物を入れるには、箱は何箱必要ですか。',46,[45,47,365],['365÷8を計算します。','あまった荷物も箱に入れます。'],'365÷8＝45あまり５。あまりの荷物のためにもう１箱必要で46箱です。',null);
