  add('decimal','advanced','水を2.5L使ったら、残りが1.75Lになりました。はじめに水は何Lありましたか。',4.25,[0.75,3.75,4.15],['はじめの量は使った量と残りの量を足して求めます。','2.5と1.75を足します。'],'2.5＋1.75＝4.25。はじめは4.25Lありました。',null);
